create or replace function t002_working_days(
  p_start in date,
  p_end   in date
) return pls_integer is
  -- Working days (Monday to Friday) between p_start and p_end, counting both dates.
  l_day   date        := trunc(p_start);
  l_count pls_integer := 0;
begin
  if p_start is null or p_end is null or trunc(p_end) < trunc(p_start) then
    return 0;
  end if;
  while l_day <= trunc(p_end) loop
    -- Check if the day is a weekday (Monday=2 to Friday=6 in Oracle's DOW function, or check if day_of_week is not Saturday (7) or Sunday (1))
    -- TRUNC(date, 'IW') returns the Monday of the week. Subtracting it from the date gives the day offset (0=Mon, 6=Sun).
    -- If the offset is 0, 1, 2, 3, or 4, it's a weekday.
    if to_char(l_day, 'D') not in ('1', '7') then -- 'D' returns 1 for Sunday, 7 for Saturday in many NLS settings, but using day of week logic is safer.
      -- A more robust check for Mon-Fri:
      if l_day - trunc(l_day, 'IW') >= 0 and l_day - trunc(l_day, 'IW') <= 4 then
        l_count := l_count + 1;
      end if;
    end if;
    l_day := l_day + 1;
  end loop;
  return l_count;
end t002_working_days;
/
